--   ('0a1ff14f-ac73-4b9e-ab4c-a4d465c78e76'::uuid, $plh${"title":"Cardinal d'une réunion et d'un produit cartésien","description":"Card(A ∪ B) = Card A + Card B − Card(A ∩ B) en contexte (activités, langues) et Card(A × B) = Card A × Card B","variations":[{"blanks":[{"expectedAnswer":"{{eval:a+b-c}}"},{"expectedAnswer":"{{z}}"}],"statement":"Dans une classe de ${{n}}$ élèves, ${{a}}$ font du sport en club, ${{b}}$ font de la musique et ${{c}}$ font les deux.\n\nNombre d'élèves qui pratiquent au moins une des deux activités : $?$\n\nNombre d'élèves qui ne pratiquent aucune des deux activités : $?$","variables":[{"name":"c","expression":"2..8"},{"name":"ga","expression":"3..12"},{"name":"a","expression":"{{eval:c+ga}}"},{"name":"gb","expression":"2..10"},{"name":"b","expression":"{{eval:c+gb}}"},{"name":"z","expression":"1..6"},{"name":"n","expression":"{{eval:a+b-c+z}}"}],"correction":{"steps":["On note $S$ l'ensemble des élèves qui font du sport et $M$ celui des élèves qui font de la musique. Les ${{c}}$ élèves qui font les deux sont comptés **deux fois** dans ${{a}}+{{b}}$ : on les retire une fois.","$\\mathrm{Card}(S\\cup M)=\\mathrm{Card}(S)+\\mathrm{Card}(M)-\\mathrm{Card}(S\\cap M)={{a}}+{{b}}-{{c}}=\\textcolor{{{color:primary.0}}}{ {{eval:a+b-c}} }$ élèves pratiquent au moins une activité.","Les autres ne pratiquent aucune des deux : ${{n}}-{{eval:a+b-c}}=\\textcolor{{{color:primary.0}}}{ {{z}} }$ élèves."]}},{"blanks":[{"expectedAnswer":"{{c}}"}],"statement":"Dans un lycée, on interroge ${{n}}$ élèves : ${{a}}$ apprennent l'espagnol, ${{b}}$ apprennent l'allemand, et ${{z}}$ n'apprennent aucune de ces deux langues.\n\nCombien d'élèves interrogés apprennent les deux langues ? $?$","variables":[{"name":"c","expression":"2..8"},{"name":"ga","expression":"3..12"},{"name":"a","expression":"{{eval:c+ga}}"},{"name":"gb","expression":"2..10"},{"name":"b","expression":"{{eval:c+gb}}"},{"name":"z","expression":"1..6"},{"name":"n","expression":"{{eval:a+b-c+z}}"}],"correction":{"steps":["On note $E$ l'ensemble des élèves qui apprennent l'espagnol et $D$ celui des élèves qui apprennent l'allemand. Les élèves qui apprennent au moins une des deux langues sont ${{n}}-{{z}}={{eval:n-z}}$ : $\\mathrm{Card}(E\\cup D)={{eval:n-z}}$.","D'après $\\mathrm{Card}(E\\cup D)=\\mathrm{Card}(E)+\\mathrm{Card}(D)-\\mathrm{Card}(E\\cap D)$ : $\\mathrm{Card}(E\\cap D)={{a}}+{{b}}-{{eval:n-z}}=\\textcolor{{{color:primary.0}}}{ {{c}} }$ élèves apprennent les deux langues."]}},{"blanks":[{"expectedAnswer":"{{c}}"}],"statement":"$A$ et $B$ sont deux ensembles finis tels que $\\mathrm{Card}(A)={{a}}$, $\\mathrm{Card}(B)={{b}}$ et $\\mathrm{Card}(A\\cup B)={{eval:a+b-c}}$.\n\n$\\mathrm{Card}(A\\cap B)=?$","variables":[{"name":"c","expression":"2..8"},{"name":"ga","expression":"3..12"},{"name":"a","expression":"{{eval:c+ga}}"},{"name":"gb","expression":"2..10"},{"name":"b","expression":"{{eval:c+gb}}"}],"correction":{"steps":["On utilise $\\mathrm{Card}(A\\cup B)=\\mathrm{Card}(A)+\\mathrm{Card}(B)-\\mathrm{Card}(A\\cap B)$.","Donc $\\mathrm{Card}(A\\cap B)=\\mathrm{Card}(A)+\\mathrm{Card}(B)-\\mathrm{Card}(A\\cup B)={{a}}+{{b}}-{{eval:a+b-c}}=\\textcolor{{{color:primary.0}}}{ {{c}} }$."]}},{"blanks":[{"expectedAnswer":"{{eval:m*(k+1)}}"},{"expectedAnswer":"{{eval:(k+1)^2}}"}],"statement":"On considère les ensembles $A=\\{1;2;\\dots;{{m}}\\}$ et $B=\\{0;1;\\dots;{{k}}\\}$.\n\n$\\mathrm{Card}(A\\times B)=?$\n\n$\\mathrm{Card}(B\\times B)=?$","variables":[{"name":"m","expression":"3..9"},{"name":"k","expression":"2..6"}],"correction":{"steps":["$\\mathrm{Card}(A)={{m}}$ et $\\mathrm{Card}(B)={{eval:k+1}}$ : attention, $B$ contient $0$, il a ${{eval:k+1}}$ éléments et non ${{k}}$.","Un couple $(x\\,;\\,y)$ de $A\\times B$ s'obtient en choisissant $x$ parmi ${{m}}$ valeurs, puis $y$ parmi ${{eval:k+1}}$ valeurs : $\\mathrm{Card}(A\\times B)=\\mathrm{Card}(A)\\times\\mathrm{Card}(B)={{m}}\\times{{eval:k+1}}=\\textcolor{{{color:primary.0}}}{ {{eval:m*(k+1)}} }$.","De même, $\\mathrm{Card}(B\\times B)={{eval:k+1}}\\times{{eval:k+1}}=\\textcolor{{{color:primary.0}}}{ {{eval:(k+1)^2}} }$."]}}],"shared":null,"test_specs":[{"answers":["16","3"],"expected":{"status":"correct"},"variables":{"c":"5","z":"3","ga":"7","gb":"4"},"description":"v0 : 16 et 3","variationIndex":0},{"answers":["21","3"],"expected":{"status":"incorrect"},"variables":{"c":"5","z":"3","ga":"7","gb":"4"},"description":"v0 : a + b sans retirer les deux (21)","variationIndex":0},{"answers":["16","-2"],"expected":{"status":"incorrect"},"variables":{"c":"5","z":"3","ga":"7","gb":"4"},"description":"v0 : aucune = n − a − b, intersection non rajoutée (−2)","variationIndex":0},{"answers":["5"],"expected":{"status":"correct"},"variables":{"c":"5","z":"3","ga":"7","gb":"4"},"description":"v1 : 5 élèves","variationIndex":1},{"answers":["2"],"expected":{"status":"incorrect"},"variables":{"c":"5","z":"3","ga":"7","gb":"4"},"description":"v1 : a + b − n (2), oubli des « aucune »","variationIndex":1},{"answers":["5"],"expected":{"status":"correct"},"variables":{"c":"5","ga":"7","gb":"4"},"description":"v2 : Card(A∩B) = 5","variationIndex":2},{"answers":["4"],"expected":{"status":"incorrect"},"variables":{"c":"5","ga":"7","gb":"4"},"description":"v2 : Card(A∪B) − Card(A) (4)","variationIndex":2},{"answers":["16","16"],"expected":{"status":"correct"},"variables":{"k":"3","m":"4"},"description":"v3 : A={1..4}, B={0..3} : 16 et 16","variationIndex":3},{"answers":["12","9"],"expected":{"status":"incorrect"},"variables":{"k":"3","m":"4"},"description":"v3 : 0 oublié dans B (12 et 9)","variationIndex":3},{"answers":["8","8"],"expected":{"status":"incorrect"},"variables":{"k":"3","m":"4"},"description":"v3 : somme au lieu du produit (8 et 8)","variationIndex":3}]}$plh$::jsonb),
--   ('219c9470-ffe0-48a6-bebf-39fb814ad613'::uuid, $plh${"title":"« Et » et « ou » : vrai ou faux ?","description":"Décider si une proposition composée avec « et » ou « ou » est vraie pour une valeur donnée de la variable","variations":[{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Soit $x$ un nombre réel. On considère la proposition $P$ : « $x{{if:s1=1|\\geqslant|>}}{{a}}$ et $x{{if:s2=1|\\leqslant|<}}{{b}}$ ».\n\nPour $x={{c}}$, la proposition $P$ est-elle vraie ou fausse ?","variables":[{"name":"a","expression":"-6..6"},{"name":"d","expression":"2..6"},{"name":"b","expression":"{{eval:a+d}}"},{"name":"t","expression":"-2..8"},{"name":"c","expression":"{{eval:a+t}}"},{"name":"s1","expression":"0..1"},{"name":"s2","expression":"0..1"},{"name":"T1","expression":"{{eval:(1+sign(c-a+s1-0.5))/2}}"},{"name":"T2","expression":"{{eval:(1+sign(b-c+s2-0.5))/2}}"},{"name":"u1","expression":"{{eval:2*T1+s1}}"},{"name":"u2","expression":"{{eval:2*T2+s2}}"}],"conditions":["t <= d+2"],"correction":{"steps":["On teste chacune des deux propositions pour $x={{c}}$.","« $x{{if:s1=1|\\geqslant|>}}{{a}}$ » est {{if:u1=3|**vraie** car ${{c}}\\geqslant{{a}}$.}}{{if:u1=2|**vraie** car ${{c}}>{{a}}$.}}{{if:u1=1|**fausse** car ${{c}}<{{a}}$.}}{{if:u1=0|**fausse** car ${{c}}\\leqslant{{a}}$.}}","« $x{{if:s2=1|\\leqslant|<}}{{b}}$ » est {{if:u2=3|**vraie** car ${{c}}\\leqslant{{b}}$.}}{{if:u2=2|**vraie** car ${{c}}<{{b}}$.}}{{if:u2=1|**fausse** car ${{c}}>{{b}}$.}}{{if:u2=0|**fausse** car ${{c}}\\geqslant{{b}}$.}}","Une proposition « $A$ et $B$ » est vraie seulement quand $A$ et $B$ sont **toutes les deux** vraies.","{{if:T1*T2=1|Ici les deux sont vraies : **$P$ est vraie** pour $x={{c}}$.|Ici au moins l'une des deux est fausse : **$P$ est fausse** pour $x={{c}}$.}}"]},"correctChoiceIndex":["{{eval:1-T1*T2}}"]},{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Soit $x$ un nombre réel. On considère la proposition $P$ : « $x{{if:s1=1|\\leqslant|<}}{{a}}$ ou $x{{if:s2=1|\\geqslant|>}}{{b}}$ ».\n\nPour $x={{c}}$, la proposition $P$ est-elle vraie ou fausse ?","variables":[{"name":"a","expression":"-6..6"},{"name":"d","expression":"2..6"},{"name":"b","expression":"{{eval:a+d}}"},{"name":"t","expression":"-2..8"},{"name":"c","expression":"{{eval:a+t}}"},{"name":"s1","expression":"0..1"},{"name":"s2","expression":"0..1"},{"name":"T1","expression":"{{eval:(1+sign(a-c+s1-0.5))/2}}"},{"name":"T2","expression":"{{eval:(1+sign(c-b+s2-0.5))/2}}"},{"name":"u1","expression":"{{eval:2*T1+s1}}"},{"name":"u2","expression":"{{eval:2*T2+s2}}"}],"conditions":["t <= d+2"],"correction":{"steps":["On teste chacune des deux propositions pour $x={{c}}$.","« $x{{if:s1=1|\\leqslant|<}}{{a}}$ » est {{if:u1=3|**vraie** car ${{c}}\\leqslant{{a}}$.}}{{if:u1=2|**vraie** car ${{c}}<{{a}}$.}}{{if:u1=1|**fausse** car ${{c}}>{{a}}$.}}{{if:u1=0|**fausse** car ${{c}}\\geqslant{{a}}$.}}","« $x{{if:s2=1|\\geqslant|>}}{{b}}$ » est {{if:u2=3|**vraie** car ${{c}}\\geqslant{{b}}$.}}{{if:u2=2|**vraie** car ${{c}}>{{b}}$.}}{{if:u2=1|**fausse** car ${{c}}<{{b}}$.}}{{if:u2=0|**fausse** car ${{c}}\\leqslant{{b}}$.}}","Une proposition « $A$ ou $B$ » est vraie dès que **l'une au moins** des deux est vraie (le « ou » mathématique n'est pas exclusif).","{{if:T1+T2=0|Ici les deux sont fausses : **$P$ est fausse** pour $x={{c}}$.|Ici au moins l'une des deux est vraie : **$P$ est vraie** pour $x={{c}}$.}}"]},"correctChoiceIndex":["{{eval:(1-T1)*(1-T2)}}"]},{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Soit $n$ un entier naturel. On considère la proposition $P$ : « $n$ est un multiple de ${{m}}$ {{if:k=1|ou|et}} $n>{{a}}$ ».\n\nPour $n={{n}}$, la proposition $P$ est-elle vraie ou fausse ?","variables":[{"name":"m","expression":"2..5"},{"name":"a","expression":"3..20"},{"name":"n","expression":"0..30"},{"name":"k","expression":"0..1"},{"name":"T1","expression":"{{eval:1-sign(mod(n,m))}}"},{"name":"T2","expression":"{{eval:(1+sign(n-a-0.5))/2}}"},{"name":"T","expression":"{{eval:T1*T2+k*(T1+T2-2*T1*T2)}}"}],"conditions":["abs(n-a) <= 8"],"correction":{"steps":["« $n$ est un multiple de ${{m}}$ » est {{if:T1=1|**vraie** : ${{n}}={{m}}\\times{{eval:n/m}}$.|**fausse** : la division de ${{n}}$ par ${{m}}$ a pour reste ${{eval:mod(n,m)}}$.}}","« $n>{{a}}$ » est {{if:T2=1|**vraie** car ${{n}}>{{a}}$.|**fausse** car ${{n}}\\leqslant{{a}}$.}}","{{if:k=1|Une proposition « $A$ ou $B$ » est vraie dès que l'une au moins des deux est vraie.|Une proposition « $A$ et $B$ » est vraie seulement quand les deux sont vraies.}}","{{if:T=1|Donc **$P$ est vraie** pour $n={{n}}$.|Donc **$P$ est fausse** pour $n={{n}}$.}}"]},"correctChoiceIndex":["{{eval:1-T}}"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"2","d":"4","t":"3","s1":"0","s2":"0"},"description":"et : 5 dans ]2;6[ : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"2","d":"4","t":"3","s1":"0","s2":"0"},"description":"et : 5 dans ]2;6[ : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"2","d":"4","t":"0","s1":"0","s2":"0"},"description":"et : x=a avec inégalité stricte : bonne réponse","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"2","d":"4","t":"0","s1":"0","s2":"0"},"description":"et : x=a avec inégalité stricte : autre choix refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"2","d":"4","t":"0","s1":"1","s2":"0"},"description":"et : x=a avec ≥ : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"2","d":"4","t":"0","s1":"1","s2":"0"},"description":"et : x=a avec ≥ : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"2","d":"4","t":"4","s1":"0","s2":"0"},"description":"et : x=b avec < : bonne réponse","variationI