insert into _plh_modeles values ('7eec7032-a49c-4662-a2af-73c9ef8f2f98', $plh$Fonctions$plh$, $plh$Généralités sur les fonctions$plh$, $plh$parité$plh$, array['1_SPE'], 'draft',
  $plh${"title":"Parité et périodicité de cosinus et sinus","description":"Reconnaître une fonction paire, impaire ou ni l'une ni l'autre ; période 2π","variations":[{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\cos x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["$\\mathbb{R}$ est symétrique par rapport à $0$ et, pour tout réel $x$, $f(-x)=\\cos(-x)=\\cos x=f(x)$.","La fonction cosinus est donc **paire** : sa courbe est symétrique par rapport à l'axe des ordonnées."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\sin x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["$\\mathbb{R}$ est symétrique par rapport à $0$ et, pour tout réel $x$, $f(-x)=\\sin(-x)=-\\sin x=-f(x)$.","La fonction sinus est donc **impaire** : sa courbe est symétrique par rapport à l'origine."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\sin({{k}}x)$.\n\nLa fonction $f$ est :","variables":[{"name":"k","expression":"2..4"}],"correction":{"steps":["Pour tout réel $x$, $f(-x)=\\sin(-{{k}}x)=-\\sin({{k}}x)=-f(x)$ car la fonction sinus est impaire.","La fonction $f$ est donc **impaire**."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\cos x{{k;+}}$.\n\nLa fonction $f$ est :","variables":[{"name":"k","expression":"1..3;±"}],"correction":{"steps":["Pour tout réel $x$, $f(-x)=\\cos(-x){{k;+}}=\\cos x{{k;+}}=f(x)$ car la fonction cosinus est paire.","La fonction $f$ est donc **paire**."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=x\\sin x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["Pour tout réel $x$, $f(-x)=(-x)\\sin(-x)=(-x)\\times(-\\sin x)=x\\sin x=f(x)$.","La fonction $f$ est donc **paire** (produit de deux fonctions impaires)."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=x\\cos x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["Pour tout réel $x$, $f(-x)=(-x)\\cos(-x)=-x\\cos x=-f(x)$.","La fonction $f$ est donc **impaire** (produit d'une fonction impaire et d'une fonction paire)."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\sin x{{k;+}}$.\n\nLa fonction $f$ est :","variables":[{"name":"k","expression":"1..3;±"}],"correction":{"steps":["$f(0)={{k}}\\neq0$ : une fonction impaire définie en $0$ y vaut $0$, donc $f$ n'est pas impaire.","$f\\left(\\dfrac{\\pi}{2}\\right)={{eval:1+k}}$ et $f\\left(-\\dfrac{\\pi}{2}\\right)={{eval:k-1}}$ : ces valeurs sont différentes, donc $f$ n'est pas paire.","La fonction $f$ n'est **ni paire ni impaire**."]},"correctChoiceIndex":["2"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=x+\\cos x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["$f(0)=1\\neq0$, donc $f$ n'est pas impaire.","$f(\\pi)=\\pi-1$ et $f(-\\pi)=-\\pi-1$ : ces valeurs sont différentes, donc $f$ n'est pas paire.","La fonction $f$ n'est **ni paire ni impaire**."]},"correctChoiceIndex":["2"]},{"choices":[{"content":"$2\\pi$"},{"content":"$\\pi$"},{"content":"$\\dfrac{\\pi}{2}$"},{"content":"$1$"}],"statement":"Complète : pour tout réel $x$, $\\sin(x+\\ldots)=\\sin x$, et c'est la plus petite valeur strictement positive qui convient.","variables":[],"correction":{"steps":["La fonction sinus est périodique de période $2\\pi$ : $\\sin(x+2\\pi)=\\sin x$.","Attention : $\\sin(x+\\pi)=-\\sin x$, ce n'est pas $\\sin x$.","Réponse : $\\textcolor{{{color:primary.0}}}{2\\pi }$."]},"correctChoiceIndex":["0"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{},"description":"variation 0 : f(x)=\\cos x, « paire » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : f(x)=\\cos x, « impaire » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : f(x)=\\cos x, « ni paire ni impaire » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 1 : f(x)=\\sin x, « paire » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{},"description":"variation 1 : f(x)=\\sin x, « impaire » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 1 : f(x)=\\sin x, « ni paire ni impaire » refusé","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 2 : f(x)=\\sin(kx), « paire » refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"k":"2"},"description":"variation 2 : f(x)=\\sin(kx), « impaire » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 2 : f(x)=\\sin(kx), « ni paire ni impaire » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"k":"2"},"description":"variation 3 : f(x)=\\cos x+k, « paire » accepté","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 3 : f(x)=\\cos x+k, « impaire » refusé","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 3 : f(x)=\\cos x+k, « ni paire ni impaire » refusé","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{},"description":"variation 4 : f(x)=x\\sin x, « paire » accepté","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 4 : f(x)=x\\sin x, « impaire » refusé","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 4 : f(x)=x\\sin x, « ni paire ni impaire » refusé","variationIndex":4,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 5 : f(x)=x\\cos x, « paire » refusé","variationIndex":5,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{},"description":"variation 5 : f(x)=x\\cos x, « impaire » accepté","variationIndex":5,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 5 : f(x)=x\\cos x, « ni paire ni impaire » refusé","variationIndex":5,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"k":"-1"},"description":"variation 6 : f(x)=\\sin x+k, « paire » refusé","variationIndex":6,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"k":"-1"},"description":"variation 6 : f(x)=\\sin x+k, « impaire » refusé","variationIndex":6,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"k":"-1"},"description":"variation 6 : f(x)=\\sin x+k, « ni paire ni impaire » accepté","variationIndex":6,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 7 : f(x)=x+\\cos x, « paire » refusé","variationIndex":7,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 7 : f(x)=x+\\cos x, « impaire » refusé","variationIndex":7,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{},"description":"variation 7 : f(x)=x+\\cos x, « ni paire ni impaire » accepté","variationIndex":7,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{},"description":"variation 8 : « 2π » accepté","variationIndex":8,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 8 : « π » refusé","variationIndex":8,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 8 : « π/2 » refusé","variationIndex":8,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 8 : « 1 » refusé","variationIndex":8,"selectedChoices":[3]}]}$plh$::jsonb,
  $plh${"title":"Parité des fonctions cosinus et sinus","description":"Reconnaître une fonction paire, impaire ou ni l'une ni l'autre (cos, sin, sin(kx), x sin x…)","variations":[{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\cos x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["$\\mathbb{R}$ est symétrique par rapport à $0$ et, pour tout réel $x$, $f(-x)=\\cos(-x)=\\cos x=f(x)$.","La fonction cosinus est donc **paire** : sa courbe est symétrique par rapport à l'axe des ordonnées."]},"correctChoiceIndex":["0"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\sin x$.\n\nLa fonction $f$ est :","variables":[],"correction":{"steps":["$\\mathbb{R}$ est symétrique par rapport à $0$ et, pour tout réel $x$, $f(-x)=\\sin(-x)=-\\sin x=-f(x)$.","La fonction sinus est donc **impaire** : sa courbe est symétrique par rapport à l'origine."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\sin({{k}}x)$.\n\nLa fonction $f$ est :","variables":[{"name":"k","expression":"2..4"}],"correction":{"steps":["Pour tout réel $x$, $f(-x)=\\sin(-{{k}}x)=-\\sin({{k}}x)=-f(x)$ car la fonction sinus est impaire.","La fonction $f$ est donc **impaire**."]},"correctChoiceIndex":["1"]},{"choices":[{"content":"paire"},{"content":"impaire"},{"content":"ni paire ni impaire"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=\\cos x{{k;+}}$.\n\nLa fonction $f$ est :","variables":[{"name":"k","expression":"1..3;±"}],"correction":{"steps":["Pour tout réel $x$, $f(-x)=\\cos(-x){{k;+}}=\\cos x{{k;+}}=f(x)$ car la fonction cosinus est paire.","La fonction $f$ est donc **paire**."]},"correctChoiceIndex":["0"]},{