n":"variation 0 : f(x)=\\cos x, « paire » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : f(x)=\\cos x, « impaire » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 0 : f(x)=\\cos x, « ni paire ni impaire » refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 1 : f(x)=\\sin x, « paire » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{},"description":"variation 1 : f(x)=\\sin x, « impaire » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{},"description":"variation 1 : f(x)=\\sin x, « ni paire ni impaire » refusé","variationIndex":1,"selectedChoices":[2]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 2 : f(x)=\\sin(kx), « paire » refusé","variationIndex":2,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"k":"2"},"description":"variation 2 : f(x)=\\sin(kx), « impaire » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 2 : f(x)=\\sin(kx), « ni paire ni impaire » refusé","variationIndex":2,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"k":"2"},"description":"variation 3 : f(x)=\\cos x+k, « paire » accepté","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 3 : f(x)=\\cos x+k, « impaire » refusé","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"k":"2"},"description":"variation 3 : f(x)=\\cos x+k, « ni paire ni impaire » refusé","variationIndex":3,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{},"description":"variation 4 : f(x)=x\\sin x, « paire » accepté