insert into _plh_modeles values ('99c772c0-3a0c-4f63-b01e-a7da4de812c4', $plh$Fonctions$plh$, $plh$Fonctions trigonométriques$plh$, $plh$équations$plh$, array['1_SPE'], 'draft',
  $plh${"title":"Équations trigonométriques : aucune solution, cos x = cos α, sin x = sin α","description":"cos x = k avec |k| > 1 et sin x = ±3/2, ±5/2 (ensemble vide) ; cos x = cos α dans ]−π ; π] ; sin x = sin α dans [0 ; 2π[","variations":[{"blanks":[{"expectedAnswer":"\\varnothing"}],"statement":"Résous dans $\\left]-\\pi\\,;\\pi\\right]$ l'équation $\\cos x={{k}}$.\n\nL'ensemble des solutions est $S=?$.","variables":[{"name":"k","expression":"2..5;±"}],"correction":{"steps":["Pour tout réel $x$, $-1\\leqslant \\cos x\\leqslant 1$ : aucun point du cercle n'a pour abscisse ${{k}}$.","```trig\nequation: cos(x) = {{k}}\nmode: points\nmesures: principales\n```","$S=\\textcolor{{{color:primary.0}}}{\\varnothing }$."]}},{"blanks":[{"expectedAnswer":"\\varnothing"}],"statement":"Résous dans $\\left[0\\,;2\\pi\\right[$ l'équation $\\sin x={{eval:p/2}}$.\n\nL'ensemble des solutions est $S=?$.","variables":[{"name":"p","expression":"3|5|-3|-5"}],"correction":{"steps":["Pour tout réel $x$, $-1\\leqslant \\sin x\\leqslant 1$ ; or $\\left|{{eval:p/2}}\\right|>1$ : aucun point du cercle n'a pour ordonnée ${{eval:p/2}}$.","```trig\nequation: sin(x) = {{p}}/2\nmode: points\n```","$S=\\textcolor{{{color:primary.0}}}{\\varnothing }$."]}},{"blanks":[{"expectedAnswer":"\\{-\\frac{\\pi}{ {{n}} };\\frac{\\pi}{ {{n}} }\\}"}],"statement":"Résous dans $\\left]-\\pi\\,;\\pi\\right]$ l'équation $\\cos x=\\cos\\frac{\\pi}{ {{n}} }$.\n\nL'ensemble des solutions est $S=?$.","variables":[{"name":"n","expression":"5|7|8|9|10|12"}],"correction":{"steps":["$\\cos x=\\cos a$ lorsque $x$ et $a$, ou $x$ et $-a$, repèrent le même point du cercle (deux points symétriques par rapport à l'axe des abscisses).","Dans $\\left]-\\pi\\,;\\pi\\right]$, les solutions sont $\\frac{\\pi}{ {{n}} }$ et $-\\frac{\\pi}{ {{n}} }$.","```trig\npreset: custom\nangles: pi/{{n}}, -pi/{{n}}\nequation: cos(x) = cos(pi/{{n}})\nmode: points\nmesures: principales\n```","$S=\\textcolor{{{color:primary.0}}}{\\left\\{-\\frac{\\pi}{ {{n}} }\\,;\\frac{\\pi}{ {{n}} }\\right\\} }$."]}},{"blanks":[{"expectedAnswer":"\\{-\\frac{ {{k}}\\pi}{ {{n}} };\\frac{ {{k}}\\pi}{ {{n}} }\\}"}],"statement":"Résous dans $\\left]-\\pi\\,;\\pi\\right]$ l'équation $\\cos x=\\cos\\frac{ {{k}}\\pi}{ {{n}} }$.\n\nL'ensemble des solutions est $S=?$.","variables":[{"name":"n","expression":"5|7|8|9"},{"name":"k","expression":"2..8"}],"conditions":["k < n","gcd(k,n) = 1"],"correction":{"steps":["$\\cos x=\\cos a$ lorsque $x$ et $a$, ou $x$ et $-a$, repèrent le même point du cercle (deux points symétriques par rapport à l'axe des abscisses).","Dans $\\left]-\\pi\\,;\\pi\\right]$, les solutions sont $\\frac{ {{k}}\\pi}{ {{n}} }$ et $-\\frac{ {{k}}\\pi}{ {{n}} }$.","```trig\npreset: custom\nangles: {{k}}pi/{{n}}, -{{k}}pi/{{n}}\nequation: cos(x) = cos({{k}}*pi/{{n}})\nmode: points\nmesures: principales\n```","$S=\\textcolor{{{color:primary.0}}}{\\left\\{-\\frac{ {{k}}\\pi}{ {{n}} }\\,;\\frac{ {{k}}\\pi}{ {{n}} }\\right\\} }$."]}},{"blanks":[{"expectedAnswer":"\\{\\frac{ {{k}}\\pi}{ {{n}} };\\frac{ {{eval:n-k}}\\pi}{ {{n}} }\\}"}],"statement":"Résous dans $\\left[0\\,;2\\pi\\right[$ l'équation $\\sin x=\\sin\\frac{ {{k}}\\pi}{ {{n}} }$.\n\nL'ensemble des solutions est $S=?$.","variables":[{"name":"n","expression":"5|7|8|9"},{"name":"k","expression":"2..7"}],"conditions":["k < n - 1","gcd(k,n) = 1"],"correction":{"steps":["$\\sin x=\\sin a$ lorsque $x$ et $a$, ou $x$ et $\\pi-a$, repèrent le même point du cercle (deux points symétriques par rapport à l'axe des ordonnées).","Dans $\\left[0\\,;2\\pi\\right[$, les solutions sont $\\frac{ {{k}}\\pi}{ {{n}} }$ et $\\pi-\\frac{ {{k}}\\pi}{ {{n}} }=\\frac{ {{eval:n-k}}\\pi}{ {{n}} }$.","```trig\npreset: custom\nangles: {{k}}pi/{{n}}, {{eval:n-k}}pi/{{n}}\nequation: sin(x) = sin({{k}}*pi/{{n}})\nmode: points\n```","$S=\\textcolor{{{color:primary.0}}}{\\left\\{\\frac{ {{k}}\\pi}{ {{n}} }\\,;\\frac{ {{eval:n-k}}\\pi}{ {{n}} }\\right\\} }$."]}}],"shared":{"blankDefaults":{"answerKind