-- Modèles neufs : chacun copie les autres colonnes de son origine, sauf le niveau (et le nœud
-- quand l'un de ses points vit sur une sous-notion voisine).
drop table if exists pg_temp._plh_neufs;
create temporary table _plh_neufs (
	id uuid primary key,
	origine uuid not null references _plh_modeles (id),
	niveau integer not null,
	contenu jsonb not null,
	-- Nœud propre (celui de son premier point) ; null : celui de l'origine.
	branche text, notion text, sous_notion text
);
insert into _plh_neufs values ('a26e6e50-aa5b-42d0-ac68-1e24a646345c', '0a1ff14f-ac73-4b9e-ab4c-a4d465c78e76', 3,
  $plh${"title":"Cardinal d'un produit cartésien","description":"Card(A × B) = Card A × Card B","variations":[{"blanks":[{"expectedAnswer":"{{eval:m*(k+1)}}"},{"expectedAnswer":"{{eval:(k+1)^2}}"}],"statement":"On considère les ensembles $A=\\{1;2;\\dots;{{m}}\\}$ et $B=\\{0;1;\\dots;{{k}}\\}$.\n\n$\\mathrm{Card}(A\\times B)=?$\n\n$\\mathrm{Card}(B\\times B)=?$","variables":[{"name":"m","expression":"3..9"},{"name":"k","expression":"2..6"}],"correction":{"steps":["$\\mathrm{Card}(A)={{m}}$ et $\\mathrm{Card}(B)={{eval:k+1}}$ : attention, $B$ contient $0$, il a ${{eval:k+1}}$ éléments et non ${{k}}$.","Un couple $(x\\,;\\,y)$ de $A\\times B$ s'obtient en choisissant $x$ parmi ${{m}}$ valeurs, puis $y$ parmi ${{eval:k+1}}$ valeurs : $\\mathrm{Card}(A\\times B)=\\mathrm{Card}(A)\\times\\mathrm{Card}(B)={{m}}\\times{{eval:k+1}}=\\textcolor{{{color:primary.0}}}{ {{eval:m*(k+1)}} }$.","De même, $\\mathrm{Card}(B\\times B)={{eval:k+1}}\\times{{eval:k+1}}=\\textcolor{{{color:primary.0}}}{ {{eval:(k+1)^2}} }$."]}}],"shared":null,"test_specs":[{"answers":["16","16"],"expected":{"status":"correct"},"variables":{"k":"3","m":"4"},"description":"v0 : A={1..4}, B={0..3} : 16 et 16","variationIndex":0},{"answers":["12","9"],"expected":{"status":"incorrect"},"variables":{"k":"3","m":"4"},"description":"v0 : 0 oublié dans B (12 et 9)","variationIndex":0},{"answers":["8","8"],"expected":{"status":"incorrect"},"variables":{"k":"3","m":"4"},"description":"v0 : somme au lieu du produit (8 et 8)","variationIndex":0}]}$plh$::jsonb,
  $plh$Ensembles$plh$, $plh$Cardinal et produit cartésien$plh$, $plh$produit cartésien$plh$);
insert into _plh_neufs values ('1e9a534f-b04c-4a1d-88fb-5aba696422e0', '219c9470-ffe0-48a6-bebf-39fb814ad613', 3,
  $plh${"title":"« Ou » : vrai ou faux ?","description":"Décider si une proposition « A ou B » est vraie pour une valeur donnée de la variable","variations":[{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Soit $x$ un nombre réel. On considère la proposition $P$ : « $x{{if:s1=1|\\leqslant|<}}{{a}}$ ou $x{{if:s2=1|\\geqslant|>}}{{b}}$ ».\n\nPour $x={{c}}$, la proposition $P$ est-elle vraie ou fausse ?","variables":[{"name":"a","expression":"-6..6"},{"name":"d","expression":"2..6"},{"name":"b","expression":"{{eval:a+d}}"},{"name":"t","expression":"-2..8"},{"name":"c","expression":"{{eval:a+t}}"},{"name":"s1","expression":"0..1"},{"name":"s2","expression":"0..1"},{"name":"T1","expression":"{{eval:(1+sign(a-c+s1-0.5))/2}}"},{"name":"T2","expression":"{{eval:(1+sign(c-b+s2-0.5))/2}}"},{"name":"u1","expression":"{{eval:2*T1+s1}}"},{"name":"u2","expression":"{{eval:2*T2+s2}}"}],"conditions":["t <= d+2"],"correction":{"steps":["On teste chacune des deux propositions pour $x={{c}}$.","« $x{{if:s1=1|\\leqslant|<}}{{a}}$ » est {{if:u1=3|**vraie** car ${{c}}\\leqslant{{a}}$.}}{{if:u1=2|**vraie** car ${{c}}<{{a}}$.}}{{if:u1=1|**fausse** car ${{c}}>{{a}}$.}}{{if:u1=0|**fausse** car ${{c}}\\geqslant{{a}}$.}}","« $x{{if:s2=1|\\geqslant|>}}{{b}}$ » est {{if:u2=3|**vraie** car ${{c}}\\geqslant{{b}}$.}}{{if:u2=2|**vraie** car ${{c}}>{{b}}$.}}{{if:u2=1|**fausse** car ${{c}}<{{b}}$.}}{{if:u2=0|**fausse** car ${{c}}\\leqslant{{b}}$.}}","Une proposition « $A$ ou $B$ » est vraie dès que **l'une au moins** des deux est vraie (le « ou » mathématique n'est pas exclusif).","{{if:T1+T2=0|Ici les deux sont fausses : **$P$ est fausse** pour $x={{c}}$.|Ici au moins l'une des deux est vraie : **$P$ est vraie** pour $x={{c}}$.}}"]},"correctChoiceIndex":["{{eval:(1-T1)*(1-T2)}}"]},{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Soit $n$ un entier naturel. On considère la proposition $P$ : « $n$ est un multiple de ${{m}}$ ou $n>{{a}}$ ».\n\nPour $n={{n}}$, la proposition $P$ est-elle vraie ou fausse ?","variables":[{"name":"m","expression":"2..5"},{"name":"a","expression":"3..20"},{"name":"n","expression":"0..30"},{"name":"T1","expression":"{{eval:1-sign(mod(n,m))}}"},{"name":"T2","expression":"{{eval:(1+sign(n-a-0.5))/2}}"},{"name":"T","expression":"{{eval:T1+T2-T1*T2}}"}],"conditions":["abs(n-a) <= 8"],"correction":{"steps":["« $n$ est un multiple de ${{m}}$ » est {{if:T1=1|**vraie** : ${{n}}={{m}}\\times{{eval:n/m}}$.|**fausse** : la division de ${{n}}$ par ${{m}}$ a pour reste ${{eval:mod(n,m)}}$.}}","« $n>{{a}}$ » est {{if:T2=1|**vraie** car ${{n}}>{{a}}$.|**fausse** car ${{n}}\\leqslant{{a}}$.}}","Une proposition « $A$ ou $B$ » est vraie dès que l'une au moins des deux est vraie.","{{if:T=1|Donc **$P$ est vraie** pour $n={{n}}$.|Donc **$P$ est fausse** pour $n={{n}}$.}}"]},"correctChoiceIndex":["{{eval:1-T}}"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"-1","d":"5","t":"2","s1":"0","s2":"0"},"description":"ou : entre les deux : bonne réponse","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"-1","d":"5","t":"2","s1":"0","s2":"0"},"description":"ou : entre les deux : autre choix refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"-1","d":"5","t":"7","s1":"0","s2":"0"},"description":"ou : au-delà de b : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"-1","d":"5","t":"7","s1":"0","s2":"0"},"description":"ou : au-delà de b : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"-1","d":"5","t":"0","s1":"1","s2":"0"},"description":"ou : x=a avec ≤ : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"-1","d":"5","t":"0","s1":"1","s2":"0"},"description":"ou : x=a avec ≤ : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"10","m":"3","n":"9"},"description":"entiers ou : 9 : bonne réponse","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"10","m":"3","n":"9"},"description":"entiers ou : 9 : autre choix refusé","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"10","m":"4","n":"7"},"description":"entiers ou : 7 : bonne réponse","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"10","m":"4","n":"7"},"description":"entiers ou : 7 : autre choix refusé","variationIndex":1,"selectedChoices":[0]}]}$plh$::jsonb,
  null, null, null);
insert into _plh_neufs values ('e05203b0-9833-4647-b6dc-39b10f2ae5be', '5426cead-c0c2-48d3-a10b-2e46714f9129', 4,
  $plh${"title":"Une implication est-elle vraie ?","description":"Décider si « si x > a, alors x > b » est vraie, ou trouver un contre-exemple","variations":[{"choices":[{"content":"Vrai"},{"content":"Faux"}],"statement":"Soit $x$ un nombre réel. On considère l'implication : « si $x{{if:s1=1|\\geqslant|>}}{{a}}$, alors $x{{if:s2=1|\\geqslant|>}}{{b}}$ ».\n\nCette implication est-elle vraie ?","variables":[{"name":"a","expression":"-8..8"},{"name":"t","expression":"-4..4"},{"name":"b","expression":"{{eval:a+t}}"},{"name":"s1","expression":"0..1"},{"name":"s2","expression":"0..1"},{"name":"Z","expression":"{{eval:1-abs(sign(t))}}"},{"name":"T","expression":"{{eval:(1+sign(-t-0.5))/2+Z*(1-s1*(1-s2))}}"},{"name":"w","expression":"{{eval:T+(1-T)*(2+Z)}}"}],"conditions":["t != 0 or s1 != s2"],"correction":{"steps":["L'implication « si $P$, alors $Q$ » est vraie quand **chaque** réel qui vérifie $P$ vérifie aussi $Q$ ; un seul réel qui vérifie $P$ sans vérifier $Q$ suffit à la rendre fausse.","{{if:w=1|Soit $x$ tel que $x{{if:s1=1|\\geqslant|>}}{{a}}$. Comme {{if:t=0|les deux bornes sont égales|${{a}}>{{b}}$}}, on obtient $x{{if:s2=1|\\geqslant|>}}{{b}}$ : **l'implication est vraie**.}}{{if:w=2|Le réel $x={{eval:(a+b)/2;d}}$ vérifie $x{{if:s1=1|\\geqslant|>}}{{a}}$, mais pas $x{{if:s2=1|\\geqslant|>}}{{b}}$ (car ${{eval:(a+b)/2;d}}<{{b}}$) : c'est un contre-exemple, **l'implication est fausse**.}}{{if:w=3|Le réel $x={{a}}$ vérifie $x\\geqslant{{a}}$, mais pas $x>{{a}}$ : c'est un contre-exemple, **l'implication est fausse**.}}"]},"correctChoiceIndex":["{{eval:1-T}}"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"3","t":"-2","s1":"0","s2":"0"},"description":"x>3 ⇒ x>1 : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"3","t":"-2","s1":"0","s2":"0"},"description":"x>3 ⇒ x>1 : autre choix refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"a":"3","t":"2","s1":"0","s2":"0"},"description":"x>3 ⇒ x>5 : bonne réponse","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","t":"2","s1":"0","s2":"0"},"description":"x>3 ⇒ x>5 : autre choix refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","t":"0","s1":"1","s2":"0"},"description":"x≥3 ⇒ x>3 : bonne réponse","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","t":"0","s1":"1","s2":"0"},"description":"x≥3 ⇒ x>3 : autre choix refusé","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"a":"3","t":"0","s1":"0","s2":"1"},"description":"x>3 ⇒ x≥3 : bonne réponse","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"a":"3","t":"0","s1":"0","s2":"1"},"description":"x>3 ⇒ x≥3 : autre choix refusé","variationIndex":0,"selectedChoices":[1]}]}$plh$::jsonb,
  null, null, null);
insert into _plh_neufs values ('bed58c24-6ead-4e6a-bd3e-3aaf2891ea00', '5426cead-c0c2-48d3-a10b-2e46714f9129', 5,
  $plh${"title":"Contraposée d'une implication","description":"Énoncer la contraposée d'une implication","variations":[{"choices":[{"content":"{{if:z=0|Si $x^2\\leqslant{{eval:a^2}}$, alors $x\\leqslant{{a}}$.}}{{if:z=1|Si $x^2<{{eval:a^2}}$, alors $x<{{a}}$.}}{{if:z=2|Si $x\\leqslant{{a}}$, alors $x^2\\leqslant{{eval:a^2}}$.}}{{if:z=3|Si $x^2>{{eval:a^2}}$, alors $x>{{a}}$.}}{{if:z=4|Si $n$ n'est pas un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}{{if:z=5|Si $n$ est un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}{{if:z=6|Si $n$ n'est pas un multiple de ${{A}}$, alors $n$ n'est pas un multiple de ${{m}}$.}}{{if:z=7|Si $n$ est un multiple de ${{m}}$, alors $n$ est un multiple de ${{A}}$.}}"},{"content":"{{if:z=0|Si $x^2>{{eval:a^2}}$, alors $x>{{a}}$.}}{{if:z=1|Si $x^2\\leqslant{{eval:a^2}}$, alors $x\\leqslant{{a}}$.}}{{if:z=2|Si $x^2<{{eval:a^2}}$, alors $x<{{a}}$.}}{{if:z=3|Si $x\\leqslant{{a}}$, alors $x^2\\leqslant{{eval:a^2}}$.}}{{if:z=4|Si $n$ est un multiple de ${{m}}$, alors $n$ est un multiple de ${{A}}$.}}{{if:z=5|Si $n$ n'est pas un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}{{if:z=6|Si $n$ est un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}{{if:z=7|Si $n$ n'est pas un multiple de ${{A}}$, alors $n$ n'est pas un multiple de ${{m}}$.}}"},{"content":"{{if:z=0|Si $x\\leqslant{{a}}$, alors $x^2\\leqslant{{eval:a^2}}$.}}{{if:z=1|Si $x^2>{{eval:a^2}}$, alors $x>{{a}}$.}}{{if:z=2|Si $x^2\\leqslant{{eval:a^2}}$, alors $x\\leqslant{{a}}$.}}{{if:z=3|Si $x^2<{{eval:a^2}}$, alors $x<{{a}}$.}}{{if:z=4|Si $n$ n'est pas un multiple de ${{A}}$, alors $n$ n'est pas un multiple de ${{m}}$.}}{{if:z=5|Si $n$ est un multiple de ${{m}}$, alors $n$ est un multiple de ${{A}}$.}}{{if:z=6|Si $n$ n'est pas un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}{{if:z=7|Si $n$ est un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}"},{"content":"{{if:z=0|Si $x^2<{{eval:a^2}}$, alors $x<{{a}}$.}}{{if:z=1|Si $x\\leqslant{{a}}$, alors $x^2\\leqslant{{eval:a^2}}$.}}{{if:z=2|Si $x^2>{{eval:a^2}}$, alors $x>{{a}}$.}}{{if:z=3|Si $x^2\\leqslant{{eval:a^2}}$, alors $x\\leqslant{{a}}$.}}{{if:z=4|Si $n$ est un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}{{if:z=5|Si $n$ n'est pas un multiple de ${{A}}$, alors $n$ n'est pas un multiple de ${{m}}$.}}{{if:z=6|Si $n$ est un multiple de ${{m}}$, alors $n$ est un multiple de ${{A}}$.}}{{if:z=7|Si $n$ n'est pas un multiple de ${{m}}$, alors $n$ n'est pas un multiple de ${{A}}$.}}"}],"statement":"{{if:k=0|Soit $x$ un nombre réel.|Soit $n$ un entier naturel.}} On considère l'implication : « si {{if:k=0|$x>{{a}}$|$n$ est un multiple de ${{A}}$}}, alors {{if:k=0|$x^2>{{eval:a^2}}$|$n$ est un multiple de ${{m}}$}} ».\n\nQuelle est sa contraposée ?","variables":[{"name":"k","expression":"0..1"},{"name":"a","expression":"1..15"},{"name":"m","expression":"2..5"},{"name":"c","expression":"2..4"},{"name":"A","expression":"{{eval:m*c}}"},{"name":"p","expression":"0..3"},{"name":"z","expression":"{{eval:4*k+p}}"}],"correction":{"steps":["La **contraposée** de « si $P$, alors $Q$ » est « si non $Q$, alors non $P$ » : on échange hypothèse et conclusion **et** on les nie toutes les deux.","{{if:k=0|La négation de $x^2>{{eval:a^2}}$ est $x^2\\leqslant{{eval:a^2}}$, et celle de $x>{{a}}$ est $x\\leqslant{{a}}$ (la négation de « $>$ » est « $\\leqslant$ », pas « $<$ »).|La négation de « $n$ est un multiple de ${{m}}$ » est « $n$ n'est pas un multiple de ${{m}}$ », et de même pour ${{A}}$.}}","La contraposée est donc : « si {{if:k=0|$x^2\\leqslant{{eval:a^2}}$|$n$ n'est pas un multiple de ${{m}}$}}, alors {{if:k=0|$x\\leqslant{{a}}$|$n$ n'est pas un multiple de ${{A}}$}} ».","Une implication et sa contraposée sont toujours **toutes les deux vraies ou toutes les deux fausses** : ici l'implication est vraie, sa contraposée aussi. (La proposition « si {{if:k=0|$x^2>{{eval:a^2}}$|$n$ est un multiple de ${{m}}$}}, alors {{if:k=0|$x>{{a}}$|$n$ est un multiple de ${{A}}$}} » est la réciproque.)"]},"correctChoiceIndex":["{{p}}"]}],"shared":null,"test_specs":[{"expected":{"status":"correct"},"variables":{"a":"3","c":"2","k":"0","m":"2","p":"1"},"description":"contraposée x>3 : bonne réponse","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"a":"3","c":"2","k":"0","m":"2","p":"1"},"description":"contraposée x>3 : autre choix refusé","variationIndex":0,"selectedChoices":[2]},{"expected":{"status":"correct"},"variables":{"a":"3","c":"3","k":"1","m":"2","p":"3"},"description":"contraposée multiples : bonne réponse","variationIndex":0,"selectedChoices":[3]},{"expected":{"status":"incorrect"},"variables":{"a":"3","c":"3","k":"1","m":"2","p":"3"},"description":"contraposée multiples : autre choix refusé","variationIndex":0,"selectedChoices":[0]}]}$plh$::jsonb,
  null, null, null);
insert into _plh_neufs values ('f96d3e43-ada2-48e5-a6a8-dc2482a4b650', '68db64b0-95a8-4173-9bae-1125a1e36ea3', 4,
  $plh${"title":"Lire un maximum ou un minimum sur une courbe","description":"Extremum d'une fonction sur [−π ; 2π], lu sur sa courbe","variations":[{"blanks":[{"expectedAnswer":"{{eval:abs(a)+b}}"}],"statement":"La courbe $\\mathcal{C}_f$ ci-dessous représente une fonction $f$ définie sur $\\mathbb{R}$.\n\n```courbe\nx: -pi ; 2*pi\ny: {{eval:-abs(a)-abs(b)-1}} ; {{eval:abs(a)+abs(b)+1}}\ngrille: pi/2 ; 1\nf(x) = {{a}}*sin(x)+({{b}})   bleu   nom=C_f\ntaille: moyenne\ndescription: Courbe d'une fonction f, tracée dans un repère pour x de −π à 2π.\n```\n\nLis sur le graphique le maximum de $f$ sur l'intervalle $\\left[-\\pi\\,;2\\pi\\right]$.\n\n$?$","variables":[{"name":"a","expression":"1..3;±"},{"name":"b","expression":"-2..2"}],"correction":{"steps":["Sur $\\left[-\\pi\\,;2\\pi\\right]$, le maximum est l'ordonnée des points les plus hauts de la courbe, par exemple le point $M$.","```courbe\nx: -pi ; 2*pi\ny: {{eval:-abs(a)-abs(b)-1}} ; {{eval:abs(a)+abs(b)+1}}\ngrille: pi/2 ; 1\nf(x) = {{a}}*sin(x)+({{b}})   bleu   nom=C_f\npoints: M({{eval:2-a/abs(a)}}*pi/2 ; f({{eval:2-a/abs(a)}}*pi/2))\ntaille: moyenne\ndescription: Courbe d'une fonction f, tracée dans un repère pour x de −π à 2π.\n```","Le maximum de $f$ sur $\\left[-\\pi\\,;2\\pi\\right]$ est $\\textcolor{{{color:primary.0}}}{{{eval:abs(a)+b}} }$."]}},{"blanks":[{"expectedAnswer":"{{eval:b-abs(a)}}"}],"statement":"La courbe $\\mathcal{C}_f$ ci-dessous représente une fonction $f$ définie sur $\\mathbb{R}$.\n\n```courbe\nx: -pi ; 2*pi\ny: {{eval:-abs(a)-abs(b)-1}} ; {{eval:abs(a)+abs(b)+1}}\ngrille: pi/2 ; 1\nf(x) = {{a}}*cos(x)+({{b}})   bleu   nom=C_f\ntaille: moyenne\ndescription: Courbe d'une fonction f, tracée dans un repère pour x de −π à 2π.\n```\n\nLis sur le graphique le minimum de $f$ sur l'intervalle $\\left[-\\pi\\,;2\\pi\\right]$.\n\n$?$","variables":[{"name":"a","expression":"1..3;±"},{"name":"b","expression":"-2..2"}],"correction":{"steps":["Sur $\\left[-\\pi\\,;2\\pi\\right]$, le minimum est l'ordonnée des points les plus bas de la courbe, par exemple le point $M$.","```courbe\nx: -pi ; 2*pi\ny: {{eval:-abs(a)-abs(b)-1}} ; {{eval:abs(a)+abs(b)+1}}\ngrille: pi/2 ; 1\nf(x) = {{a}}*cos(x)+({{b}})   bleu   nom=C_f\npoints: M({{eval:(1+a/abs(a))/2}}*pi ; f({{eval:(1+a/abs(a))/2}}*pi))\ntaille: moyenne\ndescription: Courbe d'une fonction f, tracée dans un repère pour x de −π à 2π.\n```","Le minimum de $f$ sur $\\left[-\\pi\\,;2\\pi\\right]$ est $\\textcolor{{{color:primary.0}}}{{{eval:b-abs(a)}} }$."]}}],"shared":null,"test_specs":[{"answers":["3"],"expected":{"status":"correct"},"variables":{"a":"-2","b":"1"},"description":"variation 0 : f(x)=−2sin x+1 : maximum 3","variationIndex":0},{"answers":["-1"],"expected":{"status":"incorrect"},"variables":{"a":"-2","b":"1"},"description":"variation 0 : minimum au lieu du maximum : −1","variationIndex":0},{"answers":["\\frac{3\\pi}{2}"],"expected":{"status":"incorrect"},"variables":{"a":"-2","b":"1"},"description":"variation 0 : abscisse du maximum : 3π/2","variationIndex":0},{"answers":["2+1"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"-2","b":"1"},"description":"variation 0 : calcul non terminé : 2+1","variationIndex":0},{"answers":["1"],"expected":{"status":"correct"},"variables":{"a":"1","b":"2"},"description":"variation 1 : f(x)=cos x+2 : minimum 1","variationIndex":1},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2"},"description":"variation 1 : maximum au lieu du minimum : 3","variationIndex":1},{"answers":["-1"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"2"},"description":"variation 1 : −1 (minimum de cos)","variationIndex":1},{"answers":["2-1"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"1","b":"2"},"description":"variation 1 : calcul non terminé : 2−1","variationIndex":1}]}$plh$::jsonb,
  $plh$Fonctions$plh$, $plh$Généralités sur les fonctions$plh$, $plh$extremums$plh$);
insert into _plh_neufs values ('55341e85-6782-4ccd-84a4-8b2d3ef10a80', '6c3ee9e6-3c71-4ff9-943b-22691a9a92c7', 4,
  $plh${"title":"« Ou » et intervalles","description":"Traduire une proposition composée avec « ou » par un intervalle ou une réunion d'intervalles","variations":[{"blanks":[{"expectedAnswer":"]-\\infty;{{a}}[\\cup[{{b}};+\\infty["}],"statement":"Soit $x$ un nombre réel. On considère la proposition $P$ : « $x<{{a}}$ ou $x\\geqslant{{b}}$ ».\n\nÉcris l'ensemble des réels $x$ pour lesquels $P$ est vraie sous la forme d'un intervalle ou d'une réunion d'intervalles (bornes séparées par un point-virgule).\n\n$S=?$","variables":[{"name":"a","expression":"-9..6"},{"name":"d","expression":"1..8"},{"name":"b","expression":"{{eval:a+d}}"}],"correction":{"steps":["« $x<{{a}}$ » correspond à $]-\\infty;{{a}}[$ (${{a}}$ exclu) et « $x\\geqslant{{b}}$ » à $[{{b}};+\\infty[$ (${{b}}$ inclus).","Le connecteur « ou » demande qu'**au moins une** des deux conditions soit vraie : on prend la **réunion** des deux ensembles.","$S=\\textcolor{{{color:primary.0}}}{]-\\infty;{{a}}[\\cup[{{b}};+\\infty[}$ : les réels compris entre ${{a}}$ (inclus) et ${{b}}$ (exclu) sont les seuls à ne pas convenir."]}},{"blanks":[{"expectedAnswer":"]-\\infty;{{m}}["}],"statement":"Soit $x$ un nombre réel. On considère la proposition $P$ : « $x<{{a}}$ ou $x<{{b}}$ ».\n\nÉcris l'ensemble des réels $x$ pour lesquels $P$ est vraie sous la forme d'un intervalle ou d'une réunion d'intervalles (bornes séparées par un point-virgule).\n\n$S=?$","variables":[{"name":"a","expression":"-9..9"},{"name":"b","expression":"-9..9"},{"name":"m","expression":"{{eval:max(a,b)}}"},{"name":"n","expression":"{{eval:min(a,b)}}"}],"conditions":["a != b"],"correction":{"steps":["« $x<{{a}}$ » correspond à $]-\\infty;{{a}}[$ et « $x<{{b}}$ » à $]-\\infty;{{b}}[$.","Avec « ou », il suffit qu'**une** des deux conditions soit vraie : on prend la **réunion**. Un réel strictement inférieur à ${{n}}$ est aussi strictement inférieur à ${{m}}$.","$S=]-\\infty;{{a}}[\\cup]-\\infty;{{b}}[=\\textcolor{{{color:primary.0}}}{]-\\infty;{{m}}[}$"]}}],"shared":{"blankDefaults":{"answerKind":"intervalles"}},"test_specs":[{"answers":["]-\\infty;-1[\\cup[3;+\\infty["],"expected":{"status":"correct"},"variables":{"a":"-1","d":"4"},"description":"ou : réunion","variationIndex":0},{"answers":["[3;+\\infty[\\cup]-\\infty;-1["],"expected":{"status":"correct"},"variables":{"a":"-1","d":"4"},"description":"ou : réunion dans l'autre ordre","variationIndex":0},{"answers":["[-1;3["],"expected":{"status":"incorrect"},"variables":{"a":"-1","d":"4"},"description":"ou : complémentaire","variationIndex":0},{"answers":["]-\\infty;-1]\\cup[3;+\\infty["],"expected":{"status":"incorrect"},"variables":{"a":"-1","d":"4"},"description":"ou : -1 inclus à tort","variationIndex":0},{"answers":["]-\\infty;5["],"expected":{"status":"correct"},"variables":{"a":"5","b":"-2"},"description":"ou même sens : max","variationIndex":1},{"answers":["]-\\infty;-2["],"expected":{"status":"incorrect"},"variables":{"a":"5","b":"-2"},"description":"ou même sens : min (intersection)","variationIndex":1}]}$plh$::jsonb,
  null, null, null);
